<script setup>
import {ref,watch,computed} from 'vue';
import {state,company,api,scope,useResource,notify,can,changed,captureContext,contextMatches} from '../lib/workspace';
const props=defineProps({area:String});const module=computed(()=>props.area||state.module),routine=computed(()=>module.value+'.imports');
const layout=ref(''),file=ref(null),preview=ref(null),selected=ref([]),busy=ref(false),error=ref('');
const {data:layouts}=useResource(()=>api(scope(`/module-imports/layouts?module=${module.value}`)));
const {data:history,reload}=useResource(()=>api(scope(`/module-imports?module=${module.value}&year_value=${state.period.slice(0,4)}`)));
watch(layouts,v=>{if(!v.some(x=>x.id===layout.value))layout.value=v[0]?.id||''});
watch(()=>[state.companyId,state.period.slice(0,4),module.value],()=>{preview.value=null;selected.value=[];file.value=null;error.value=''});
const spec=computed(()=>layouts.value.find(x=>x.id===layout.value));
const encode=f=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});
async function run(action){if(busy.value||state.contextBusy)return;const ctx=captureContext(),guard={token:Symbol('operation'),name:'Importação em processamento'};if(!state.editor)state.editor=guard;busy.value=true;error.value='';try{await action(ctx)}catch(e){if(contextMatches(ctx))error.value=e.message}finally{busy.value=false;if(state.editor?.token===guard.token)state.editor=null}}
function show(p){preview.value=p;selected.value=p.records.filter(r=>r._eligibility.status==='eligible').map(r=>r._selection)}
async function analyze(){await run(async ctx=>{if(!file.value)throw Error('Selecione um CSV.');if(file.value.size>128*1024*1024)throw Error('Limite técnico de 128 MiB por arquivo. Divida o pacote e tente novamente.');const f=file.value,l=layout.value,area=module.value;const content=await encode(f);const p=await api(scope('/module-imports/preview',ctx.companyId),{method:'POST',context:ctx,body:{module:area,year:Number(ctx.year),layout:l,filename:f.name,content_base64:content}});if(contextMatches(ctx))show(p);await reload()})}
async function inspect(id){await run(async ctx=>{const p=await api(scope(`/module-imports/${id}?module=${module.value}`,ctx.companyId),{context:ctx});if(contextMatches(ctx))show(p)})}
async function confirm(){await run(async ctx=>{const p=preview.value;p.result=await api(scope(`/module-imports/${p.id}/confirm`,ctx.companyId),{method:'POST',context:ctx,body:{module:module.value,fingerprint:p.fingerprint,selected:selected.value}});notify('Registros selecionados importados. Recusas preservadas na prévia.');changed();await reload()})}
function model(){const blob=new Blob(['\uFEFF'+spec.value.fields.join(';')+'\r\n'],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=layout.value+'.csv';a.click();URL.revokeObjectURL(url)}
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">IMPORTAÇÕES · {{module==='accounting'?'CONTÁBIL':'FINANCEIRO'}}</div><h1>Importar com conferência</h1><p>{{company?.name}} · Exercício {{state.period.slice(0,4)}} · regras operacionais da empresa</p></div></header>
<section class="panel"><div class="panel-body"><div class="form-grid"><label>Leiaute<select v-model="layout" aria-label="Leiaute"><option v-for="l in layouts" :value="l.id">{{l.name}} · {{l.id}}</option></select></label><label>Arquivo CSV UTF-8<input type="file" accept=".csv" @change="file=$event.target.files[0]"/></label></div><p>Separador ponto e vírgula; datas AAAA-MM-DD; valores com ponto decimal. IDs da origem devem permanecer estáveis nas reimportações. Débitos e créditos de um lançamento usam o mesmo ID. Contas e centros são identificados pelo código de acesso.</p><code class="wrap-code">{{spec?.fields.join(';')}}</code><div class="toolbar"><button class="button outline" @click="model" :disabled="!spec">Baixar cabeçalho</button><button class="button primary" v-if="can(routine,'import')" @click="analyze" :disabled="busy||!file">Gerar prévia</button></div><p v-if="error" class="message error" role="alert">{{error}}</p></div></section>
<section v-if="preview" class="panel"><div class="panel-heading"><h2>Conferência do lote {{preview.id}}</h2><a v-if="can(routine,'export')" :href="`/api${scope(`/module-imports/${preview.id}/original?module=${module}`)}`" class="button outline">Original</a></div><div class="table-scroll"><table><thead><tr><th>Selecionar</th><th>Linhas</th><th>Registro</th><th>Competência</th><th>Diagnóstico</th></tr></thead><tbody><tr v-for="r in preview.records" :key="r._selection"><td><input type="checkbox" v-model="selected" :value="r._selection" :disabled="r._eligibility.status!=='eligible'||!!preview.result" :aria-label="`Selecionar registro ${r._selection}`"/></td><td>{{r.source_rows.join(', ')}}</td><td>{{r.payload.document||r.payload.access_code}} · {{r.payload.history||r.payload.description||r.payload.name}}</td><td>{{r._eligibility.period}}</td><td>{{r._eligibility.reason}}</td></tr></tbody></table></div><footer class="panel-action"><span>{{selected.length}} selecionados de {{preview.records.length}}. A confirmação é atômica.</span><button v-if="!preview.result&&can(routine,'import')" class="button primary" :disabled="busy||!selected.length" @click="confirm">Confirmar selecionados</button><span v-else-if="preview.result" class="badge success">{{preview.result.written.length}} processados · {{preview.result.refused.length}} não selecionados</span></footer></section>
<section class="panel"><div class="panel-heading"><h2>Histórico deste exercício</h2></div><div class="table-scroll"><table><thead><tr><th>Arquivo</th><th>Leiaute</th><th>Situação</th><th></th></tr></thead><tbody><tr v-for="h in history"><td>{{h.filename}}</td><td>{{h.layout}}</td><td>{{h.confirmed?'Confirmado':'Prévia'}}</td><td><button class="text-button" @click="inspect(h.id)">Conferir</button></td></tr></tbody></table></div></section></div></template>
